"""QA 240 D repro (generated by tools/qa/qa_d_core.py). Signature: stderr|ui/menu_sets.py:605|TypeError: Converting py args to operator properties:: keyword "value" unrecognized

Run: ALLSET_SANDBOX=qa_d python tests/run.py --no-build -k __none__ --extra tools/qa/repro_d_2_679.py
"""
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path

_spec = spec_from_file_location('qa_d_core', Path(__file__).resolve().parent / 'qa_d_core.py')
core = module_from_spec(_spec)
_spec.loader.exec_module(core)

ACTIONS = [
 {
  "kind": "mark",
  "menu": "SHIFT_EDGE",
  "path": "SHIFT_EDGE/3:Circularize Components",
  "w": 1
 }
]
SIGNATURE = "stderr|ui/menu_sets.py:605|TypeError: Converting py args to operator properties:: keyword \"value\" unrecognized"


def test_repro():
    mk = core.Monkey()
    mk.run(ACTIONS)
    hits = [f for f in mk.failures if f[1] == SIGNATURE]
    assert not hits, hits[0][2][-1500:]
